        m = re.search(r'<native-record>(.*?)</native-record>', raw, re.S)
        return n, m.group(1).strip() if m else None
    if ext == 'html':
        m = re.search(r'</dl><p>(.*?)</p>', raw, re.S)
        return n, html.unescape(m.group(1).strip()) if m else None
